const kindSuffix=kind=>({major:'',minor:'-',augmented:'+',diminished:'o',dominant:'7','major-seventh':'^7','minor-seventh':'-7','half-diminished':'h7','diminished-seventh':'o7','major-sixth':'6','minor-sixth':'-6','suspended-fourth':'sus'}[kind]??null);
