  const fifths=Number(tagText(text,'fifths')||0),mode=tagText(text,'mode')||'major',majorKeys=['C','G','D','A','E','B','F#','C#'],flatMajor=['C','F','Bb','Eb','Ab','Db','Gb','Cb'],minorKeys=['A','E','B','F#','C#','G#','D#','A#'],flatMinor=['A','D','G','C','F','Bb','Eb','Ab'];
